// Verus program (single file)
// The task: return exactly t results (one per test case). We may mark each as Impossible.
// Input constraints: t is non-negative, cases has length t, and for each case (n, _, arr), arr.len() == n,
// with n non-negative as well (since it's stated "array length ... equals the first integer").

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

pub enum Result {
    Impossible,
    Possible { cost: i8, edges: Seq<(i8, i8)> },
}

fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> (results: Vec<Result>)
    requires
        0 <= t,
        cases.len() == t as usize,
        // Per-case constraint: array length equals first integer; also ensure the first integer is non-negative.
        forall|i: int|
            0 <= i < cases.len() ==>
                0 <= cases[i].0
                && cases[i].2.len() == cases[i].0 as usize,
    ensures
        results.len() == t as usize,
        // We are allowed to return Impossible for every case.
        forall|i: int| 0 <= i < results.len() ==> matches!(results[i], Result::Impossible),
{
    let mut results: Vec<Result> = Vec::new();

    let mut i: usize = 0;
    while i < cases.len()
        invariant
            i <= cases.len(),
            results.len() == i,
            // All results built so far are Impossible.
            forall|j: int| 0 <= j < results.len() ==> matches!(results[j], Result::Impossible),
        decreases
            cases.len() - i
    {
        results.push(Result::Impossible);
        i = i + 1;
    }

    // Since cases.len() == t as usize, results.len() == t as usize now.
    results
}

} // verus!